        />
        {view === "routes" && (
          <>
            <ToggleGroup<RankLens>
              label="Rank by"
              value={lens}
              onChange={setLens}
              options={[
                { id: "bfShare", label: "BF share" },
                { id: "eafShare", label: "EAF share" },
                { id: "crude", label: "Crude Mt" },
                { id: "processMt", label: "Process Mt" },
