"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BF_SHARE_LADDER,
  GLOBAL_ROUTE_MIX,
  HEADLINE,
  INTENSITY_PATH,
  PEER_CONTRAST,
  ROUTE_STACK,
  SOURCE_NOTE,
  chinaIndiaBfDominance,
  fmtIntensity,
  fmtMt,
  fmtPct,
  rankedCountries,
  regionProcessRollup,
  scatterPoints,
  type RankLens,
  type RegionFilter,
} from "@/data/blast-furnace-vs-eaf-steel-by-country-2026-data";

// viz-types: stacked BF/EAF bars, BF-share ladder, peer contrast bars, global route donut, intensity path composed, BF-share vs intensity scatter | layout: default

type ViewId = "routes" | "peers" | "path" | "scatter";

const BF = "#b45309";
const EAF = "#0e7490";
const NAVY = "#0f172a";
const SLATE = "#64748b";
const AMBER = "#d97706";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function BlastFurnaceVsEafSteelByCountry2026Dashboard() {
  const [view, setView] = useState<ViewId>("routes");
  const [lens, setLens] = useState<RankLens>("bfShare");
  const [region, setRegion] = useState<RegionFilter>("all");

  const dominance = useMemo(() => chinaIndiaBfDominance(), []);
  const ranked = useMemo(() => rankedCountries(lens, region), [lens, region]);
  const barData = useMemo(
    () =>
      ranked.slice(0, 12).map((r) => ({
